import * as T from 'three';
export const vec=a=>new T.Vector3(...a);
const uid=()=>crypto.randomUUID();
export function contains(poly,x,y,margin=0){let inside=false,min=Infinity;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside;const dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1)));min=Math.min(min,Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy));}return (inside||min<1e-7)&&min+1e-7>=margin;}
export function panelFrame(points){const o=vec(points[0]),u=vec(points[1]).sub(o).normalize();let n=new T.Vector3();for(let i=2;i<points.length;i++){n.crossVectors(u,vec(points[i]).sub(o));if(n.length()>.00001)break;}if(n.length()<.00001)throw Error('A panel needs at least three distinct corners.');n.normalize();const v=new T.Vector3().crossVectors(n,u),raw=points.map(a=>{const d=vec(a).sub(o);return[d.dot(u),d.dot(v)];});const minX=Math.min(...raw.map(a=>a[0])),maxX=Math.max(...raw.map(a=>a[0])),minY=Math.min(...raw.map(a=>a[1])),maxY=Math.max(...raw.map(a=>a[1]));const origin=o.clone().addScaledVector(u,(minX+maxX)/2).addScaledVector(v,minY);return{origin,u,v,n,w:maxX-minX,h:maxY-minY,outline:raw.map(a=>[a[0]-(minX+maxX)/2,a[1]-minY]),q:new T.Quaternion().setFromRotationMatrix(new T.Matrix4().makeBasis(u,v,n))};}
export function localToGlobal(config,p){if(config.vertices){const f=panelFrame(config.vertices.map(v=>v.p));return f.origin.clone().addScaledVector(f.u,p[0]).addScaledVector(f.v,p[1]).addScaledVector(f.n,p[2]||0);}return vec(p).applyAxisAngle(new T.Vector3(1,0,0),T.MathUtils.degToRad(config.angle)).applyAxisAngle(new T.Vector3(0,1,0),config.rot).add(new T.Vector3(config.x,.32+(config.elevation||0),config.z));}
export function globalToLocal(config,p){const f=panelFrame(config.vertices.map(v=>v.p)),d=p.clone().sub(f.origin);return[d.dot(f.u),d.dot(f.v),d.dot(f.n)];}
export function toModel(configs){const vertices={},faces=[];configs.forEach((c,i)=>{const id=c.id||'legacy-'+i;const vs=c.vertices||[[-c.w/2,0,0],[c.w/2,0,0],[c.w/2,c.h,0],[-c.w/2,c.h,0]].map(p=>({id:uid(),p:localToGlobal(c,p).toArray()}));const ids=vs.map(v=>{let key=v.id;if(!c.vertices){const existing=Object.keys(vertices).find(k=>vec(vertices[k]).distanceTo(vec(v.p))<.001);if(existing)key=existing;}vertices[key]=[...v.p];return key;});faces.push({id,sourceId:id,name:c.name,color:c.color,ids,protected:!!c.protected,rest:Object.fromEntries(ids.map(id=>[id,[...vertices[id]]]))});});return{vertices,faces};}
export function toConfigs(model){validate(model);return model.faces.map(f=>{const vertices=f.ids.map(id=>({id,p:[...model.vertices[id]]})),p=panelFrame(vertices.map(v=>v.p));return{id:f.id,sourceId:f.sourceId,name:f.name,color:f.color,vertices,sourceVertices:f.rest?f.ids.map(id=>f.rest[id]):null,w:p.w,h:p.h,x:p.origin.x,z:p.origin.z,elevation:p.origin.y-.32,rot:0,angle:T.MathUtils.radToDeg(Math.asin(Math.max(-1,Math.min(1,-p.n.y))))};});}
export function geometry(config){const f=panelFrame(config.vertices.map(v=>v.p)),s=new T.Shape(f.outline.map(p=>new T.Vector2(...p))),g=new T.ExtrudeGeometry(s,{depth:.25,bevelEnabled:false,steps:1});g.translate(0,0,-.125);const uv=g.attributes.uv,pos=g.attributes.position;for(let i=0;i<uv.count;i++)uv.setXY(i,pos.getX(i)/f.w+.5,pos.getY(i)/f.h);g.parameters.height=f.h;return g;}
export function validate(m){if(!m.faces.length||m.faces.length>100)throw Error('Keep the wall between 1 and 100 panels.');for(const face of m.faces){const points=face.ids.map(id=>m.vertices[id]);if(points.some(p=>!p||p.some(x=>!Number.isFinite(x)||Math.abs(x)>100)))throw Error('Corner coordinates are outside the editable area.');const f=panelFrame(points);if(f.w<.08||f.h<.08)throw Error('A panel is too small. Keep at least 8 cm between its edges.');if(points.some(p=>Math.abs(vec(p).sub(f.origin).dot(f.n))>.004))throw Error('This would twist a flat panel. Split it first, or move along the shared edge.');let sign=0;const a=f.outline;for(let i=0;i<a.length;i++){const p=a[i],q=a[(i+1)%a.length],r=a[(i+2)%a.length],c=(q[0]-p[0])*(r[1]-q[1])-(q[1]-p[1])*(r[0]-q[0]);if(Math.abs(c)>.00001){if(sign&&Math.sign(c)!==sign)throw Error('Keep panels convex. Split the panel before making an inward corner.');sign=Math.sign(c);}}if(!sign)throw Error('Panel corners cannot lie on a single line.');}}
export function edges(m,f){return f.ids.map((a,i)=>({a,b:f.ids[(i+1)%f.ids.length]}));}
export function neighbours(m,a,b){return m.faces.filter(f=>edges(m,f).some(e=>(e.a===a&&e.b===b)||(e.b===a&&e.a===b)));}
export function extend(m,faceId,edge,length,angle=0,triangle=false){const f=m.faces.find(f=>f.id===faceId),a=f.ids[edge],b=f.ids[(edge+1)%f.ids.length];if(neighbours(m,a,b).length>1)throw Error('Extend an outside edge. This edge already joins two panels.');const av=vec(m.vertices[a]),bv=vec(m.vertices[b]),axis=bv.clone().sub(av).normalize(),normal=panelFrame(f.ids.map(id=>m.vertices[id])).n,out=new T.Vector3().crossVectors(axis,normal).applyAxisAngle(axis,T.MathUtils.degToRad(angle)).multiplyScalar(length);const ids=[b,a];if(triangle){const c=uid();m.vertices[c]=av.clone().lerp(bv,.5).add(out).toArray();ids.push(c);}else{for(const p of [av,bv]){const c=uid();m.vertices[c]=p.clone().add(out).toArray();ids.push(c);}}const id=uid();m.faces.push({id,sourceId:null,ids,name:'Panel '+(m.faces.length+1),color:f.color});validate(m);return id;}
export function fold(m,faceId,edge,degrees){const f=m.faces.find(f=>f.id===faceId),e=edges(m,f)[edge],moving=new Set([f.id]),queue=[f];while(queue.length){const p=queue.pop();for(const k of edges(m,p)){if((k.a===e.a&&k.b===e.b)||(k.a===e.b&&k.b===e.a))continue;for(const n of neighbours(m,k.a,k.b))if(!moving.has(n.id)){moving.add(n.id);queue.push(n);}}}const other=neighbours(m,e.a,e.b).find(x=>x.id!==f.id);if(other&&moving.has(other.id))throw Error('This hinge belongs to a closed loop. Choose an outside branch.');const ids=new Set(m.faces.filter(f=>moving.has(f.id)).flatMap(f=>f.ids));for(const f of m.faces.filter(f=>!moving.has(f.id)))for(const id of f.ids)if(ids.has(id)&&id!==e.a&&id!==e.b)throw Error('This corner also connects to a fixed panel. Choose another hinge.');const a=vec(m.vertices[e.a]),axis=vec(m.vertices[e.b]).sub(a).normalize();for(const id of ids)if(id!==e.a&&id!==e.b)m.vertices[id]=vec(m.vertices[id]).sub(a).applyAxisAngle(axis,T.MathUtils.degToRad(degrees)).add(a).toArray();validate(m);}
export function split(m,faceId,edgeA,tA,edgeB,tB){const f=m.faces.find(f=>f.id===faceId);if(edgeA===edgeB)throw Error('Draw between two different edges.');const original=[...f.ids],ids=[];const added=[];for(let i=0;i<original.length;i++){ids.push(original[i]);if(i===edgeA||i===edgeB){const t=i===edgeA?tA:tB,a=original[i],b=original[(i+1)%original.length];if(t<.02){added.push(a);}else if(t>.98){added.push(b);}else{const id=uid();m.vertices[id]=vec(m.vertices[a]).lerp(vec(m.vertices[b]),t).toArray();if(f.rest)f.rest[id]=vec(f.rest[a]).lerp(vec(f.rest[b]),t).toArray();ids.push(id);added.push(id);for(const n of m.faces.filter(x=>x!==f)){const j=n.ids.findIndex((v,k)=>v===b&&n.ids[(k+1)%n.ids.length]===a);if(j>=0){n.ids.splice(j+1,0,id);if(n.rest)n.rest[id]=vec(n.rest[a]).lerp(vec(n.rest[b]),t).toArray();}}}}}const [a,b]=added,ia=ids.indexOf(a),ib=ids.indexOf(b),lo=Math.min(ia,ib),hi=Math.max(ia,ib),first=ids.slice(lo,hi+1),second=[...ids.slice(hi),...ids.slice(0,lo+1)];if(first.length<3||second.length<3)throw Error('Choose a cut through the panel interior.');f.ids=first;const id=uid();m.faces.push({...f,id,ids:second,name:f.name+' · split'});validate(m);return id;}
export function preset(kind,width=6,height=4.2,depth=1.5){const m={vertices:{},faces:[]},v=p=>{const id=uid();m.vertices[id]=p;return id;};const a=v([-width/2,.32,-4]),b=v([width/2,.32,-4]),c=v([width/2,height+.32,-4]),d=v([-width/2,height+.32,-4]);m.faces.push({id:uid(),sourceId:null,name:'Main wall',color:'#bfccbb',ids:[a,b,c,d]});const f=m.faces[0];if(kind==='corner'||kind==='arete')extend(m,f.id,1,width*.55,kind==='corner'?-90:90);if(kind==='overhang'||kind==='cave'){m.vertices[c][1]=m.vertices[d][1]=height*.65+.32;m.vertices[c][2]=m.vertices[d][2]=-4+depth;extend(m,f.id,2,height*.35, T.MathUtils.radToDeg(Math.atan2(depth,height*.65)));if(kind==='cave'){const top=m.faces.at(-1);extend(m,top.id,2,depth,-90);}}if(kind==='boulder'){const side=extend(m,f.id,1,depth,-90);extend(m,side,2,width,-90);extend(m,f.id,3,depth,-90);extend(m,f.id,2,depth,-90);}const keys=Object.keys(m.vertices);for(let i=0;i<keys.length;i++)for(let j=i+1;j<keys.length;j++)if(vec(m.vertices[keys[i]]).distanceTo(vec(m.vertices[keys[j]]))<.00001)for(const face of m.faces)face.ids=face.ids.map(id=>id===keys[j]?keys[i]:id);validate(m);return m;}

// Map existing route positions through the same face deformation as the wall.
export function mapSurface(oldConfig,newConfigs,point){
 const oldId=oldConfig.id,world=localToGlobal(oldConfig,[point[0],point[1],0]);
 const candidates=newConfigs.map((c,i)=>({c,i})).filter(({c})=>c.sourceId===oldId||c.id===oldId);
 for(const {c,i} of candidates){const rest=c.sourceVertices||c.vertices.map(v=>v.p),rf=panelFrame(rest),d=world.clone().sub(rf.origin),x=d.dot(rf.u),y=d.dot(rf.v);if(!contains(rf.outline,x,y))continue;
  const a=vec(rest[0]);for(let k=1;k<rest.length-1;k++){const b=vec(rest[k]),v=vec(rest[k+1]),bary=T.Triangle.getBarycoord(world,a,b,v,new T.Vector3());if(!bary||Math.min(bary.x,bary.y,bary.z)<-.00001)continue;const target=vec(c.vertices[0].p).multiplyScalar(bary.x).addScaledVector(vec(c.vertices[k].p),bary.y).addScaledVector(vec(c.vertices[k+1].p),bary.z),nf=panelFrame(c.vertices.map(v=>v.p));target.addScaledVector(nf.n,point[2]||0);const oldX=oldConfig.vertices?panelFrame(oldConfig.vertices.map(v=>v.p)).u:localToGlobal(oldConfig,[1,0,0]).sub(localToGlobal(oldConfig,[0,0,0]));const shift=T.Triangle.getBarycoord(world.clone().addScaledVector(oldX,.01),a,b,v,new T.Vector3());const along=vec(c.vertices[0].p).multiplyScalar(shift.x-bary.x).addScaledVector(vec(c.vertices[k].p),shift.y-bary.y).addScaledVector(vec(c.vertices[k+1].p),shift.z-bary.z);return{sector:i,point:globalToLocal(c,target),rotation:Math.atan2(along.dot(nf.v),along.dot(nf.u))};}}
 return null;
}

export function checkIntersections(m){
 const records=m.faces.map(f=>{const points=f.ids.map(id=>vec(m.vertices[id])),frame=panelFrame(points.map(p=>p.toArray()));return{f,points,frame,box:new T.Box3().setFromPoints(points)};});
 for(let i=0;i<records.length;i++)for(let j=i+1;j<records.length;j++){
  const a=records[i],b=records[j];if(!a.box.intersectsBox(b.box))continue;
  const parallel=Math.abs(a.frame.n.dot(b.frame.n))>.99999,coplanar=parallel&&Math.abs(b.points[0].clone().sub(a.frame.origin).dot(a.frame.n))<.002;
  if(coplanar){for(const [u,v] of [[a,b],[b,a]]){const center=u.points.reduce((s,p)=>s.add(p),new T.Vector3()).divideScalar(u.points.length);for(const p of [...u.points,center]){const d=p.clone().sub(v.frame.origin);if(contains(v.frame.outline,d.dot(v.frame.u),d.dot(v.frame.v),.005))throw Error('Two panels overlap. Move or fold them apart before applying.');}}continue;}
  if(parallel)continue;
  for(const [u,v] of [[a,b],[b,a]])for(let k=0;k<u.points.length;k++){const start=u.points[k],end=u.points[(k+1)%u.points.length],delta=end.clone().sub(start),length=delta.length(),ray=new T.Ray(start,delta.normalize());for(let t=1;t<v.points.length-1;t++){const hit=ray.intersectTriangle(v.points[0],v.points[t],v.points[t+1],false,new T.Vector3());if(!hit)continue;const dist=hit.distanceTo(start);if(dist<.003||dist>length-.003)continue;const p=hit.clone().sub(v.frame.origin);if(contains(v.frame.outline,p.dot(v.frame.u),p.dot(v.frame.v),.003))throw Error('A panel passes through another panel. Reduce the fold or move the corner.');}}
 }
}
